import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{intakeRoot,validateIntake,createPacket,renderPacket,inspectJpeg}from'./plexus-ultrasound-review-packet-20261026.mjs';
const original=JSON.parse(fs.readFileSync(intakeRoot+'/INTAKE.json')),copy=()=>structuredClone(original);
test('five original JPEGs retain exact byte identities, dimensions and metadata limits',()=>{const r=validateIntake(intakeRoot,copy());assert.equal(r.figures.length,5);assert.equal(r.totalBytes,261917);});
test('noncommercial, substituted, redirected and foreign-source descriptions refuse',()=>{for(const mutate of [m=>m.article.licenseUrl='https://creativecommons.org/licenses/by-nc/4.0/',m=>m.article.htmlSha256='0'.repeat(64),m=>m.article.doi='unverified',m=>m.figures[0].sourceUrl='https://elsewhere.invalid/x.jpg',m=>m.figures[0].httpStatus=302,m=>m.figures[0].redirectLocation='https://elsewhere.invalid']){const m=copy();mutate(m);assert.throws(()=>validateIntake(intakeRoot,m));}});
test('foreign paths, altered hashes, byte caps and geometry/admission fields refuse',()=>{for(const mutate of [m=>m.figures[0].file='../tzaf003f2.jpg',m=>m.figures[0].sha256='0'.repeat(64),m=>m.figures[0].bytes=0,m=>m.limits.maxBytesPerFigure=10**9,m=>m.figures[0].clinicalApproved=true,m=>m.figures[0].imageTo3DTransform={},m=>m.figures[0].mask=null,m=>m.privacyCleared=true]){const m=copy();mutate(m);assert.throws(()=>validateIntake(intakeRoot,m));}});
test('missing, duplicated, reordered and false image metadata refuse',()=>{for(const mutate of [m=>m.figures.pop(),m=>m.figures[1]=m.figures[0],m=>m.figures.reverse(),m=>m.figures[0].imageMetadata.widthPixels=761,m=>m.figures[0].imageMetadata.exifApp1SegmentCount=1]){const m=copy();mutate(m);assert.throws(()=>validateIntake(intakeRoot,m));}});
test('malformed JPEG markers and unbounded segment lengths refuse',()=>{for(const bytes of [Buffer.alloc(6),Buffer.from('ffd8ffe10000ffd9','hex'),Buffer.from('ffd8ffe1ffff00ffd9','hex'),Buffer.from('ffd8ffda0002ffd9','hex')])assert.throws(()=>inspectJpeg(bytes));});
test('review revision is deterministic and no geometry, mask, clearance or inbox is fabricated',()=>{const a=createPacket(intakeRoot),b=createPacket(intakeRoot);assert.equal(a.revisionSha256,b.revisionSha256);assert.equal(a.figures.filter(r=>r.rightsHold).length,1);assert.equal(a.figures.find(r=>r.figure===6).rightsHold.includes('Schematic'),true);for(const r of a.figures){assert.equal(r.patientLaterality,null);assert.equal(r.fmaId,null);assert.equal(r.atlasStructureId,null);assert.equal(r.mask,null);assert.equal(r.imageTo3DTransform,null);assert.equal(r.clinicalReview,'not-reviewed');}assert.equal(a.reviewInboxImported,false);assert.equal(a.readinessEnabled,false);assert.equal(a.license.publicationClearance,false);});
test('offline review keeps attribution and source pixels together without approval controls or scripts',()=>{const html=renderPacket(createPacket(intakeRoot));assert.equal((html.match(/<img /g)||[]).length,5);assert.equal((html.match(/Unmodified JPEG/g)||[]).length,5);assert(html.includes('CC BY 4.0'));assert(html.includes('James F. Griffith'));assert(html.includes('form-action &#39;none&#39;')||html.includes("form-action 'none'"));assert(!/<script|<form|approve\s*<\/button>/i.test(html));assert(html.includes('not imported into Clinical Review'));});
